import{_ as i,o as t,c as h,a3 as o}from"./chunks/framework.DX_KL3e0.js";const a="/help/screenshots/bieu-mau/tong-quan.png",u="/help/screenshots/bieu-mau/form-cong-khai.png",p=JSON.parse('{"title":"Biểu Mẫu","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/bieu-mau.md","filePath":"chuc-nang/bieu-mau.md","lastUpdated":1782142733000}'),g={name:"chuc-nang/bieu-mau.md"};function r(c,n,e,s,l,m){return t(),h("div",null,[...n[0]||(n[0]=[o('<h1 id="bieu-mau" tabindex="-1">Biểu Mẫu <a class="header-anchor" href="#bieu-mau" aria-label="Permalink to &quot;Biểu Mẫu&quot;">​</a></h1><p>Module <strong>Biểu Mẫu</strong> cho phép tạo biểu mẫu nội bộ kiểu Google Forms, chia sẻ qua <strong>link công khai</strong> (không cần đăng nhập) và thu thập phản hồi. Bên cạnh đó, hệ thống còn có <strong>biểu mẫu thông tin nhận việc</strong> chuyên dụng cho nhân sự mới (onboarding).</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/bieu-mau</code> (kho biểu mẫu) · <code>/bieu-mau/{id}</code> (cấu hình một biểu mẫu).</li><li><strong>Link công khai biểu mẫu thường:</strong> <code>/forms/{token}</code> — ai có link đều điền được, không cần tài khoản.</li><li><strong>Biểu mẫu nhận việc (onboarding):</strong> <code>/onboarding/thong-tin-nhan-su-dau-vao</code> — link cố định, công khai.</li></ul></div><h2 id="kho-bieu-mau" tabindex="-1">Kho biểu mẫu <a class="header-anchor" href="#kho-bieu-mau" aria-label="Permalink to &quot;Kho biểu mẫu&quot;">​</a></h2><p><img src="'+a+'" alt="Trang Biểu mẫu"></p><p>Mỗi thẻ biểu mẫu cho biết trạng thái, số phản hồi đã thu, số trường, kèm hai nút <strong>Quản lý</strong> và <strong>Copy link công khai</strong>.</p><h3 id="tao-bieu-mau-moi" tabindex="-1">Tạo biểu mẫu mới <a class="header-anchor" href="#tao-bieu-mau-moi" aria-label="Permalink to &quot;Tạo biểu mẫu mới&quot;">​</a></h3><ol><li>Nhấn <strong>Tạo Biểu Mẫu</strong>.</li><li>Nhập <strong>Tiêu đề</strong> (bắt buộc) và mô tả (tùy chọn).</li><li>Nhấn <strong>Tạo &amp; Cấu Hình</strong> — biểu mẫu mới có sẵn trường <em>Họ và Tên</em>; bạn thêm các trường khác ở trang quản lý.</li></ol><h2 id="cau-hinh-mot-bieu-mau" tabindex="-1">Cấu hình một biểu mẫu <a class="header-anchor" href="#cau-hinh-mot-bieu-mau" aria-label="Permalink to &quot;Cấu hình một biểu mẫu&quot;">​</a></h2><p>Tại trang <code>/bieu-mau/{id}</code> có hai tab:</p><ul><li><strong>Trường (Fields):</strong> thêm trường mới, chọn kiểu dữ liệu, <strong>bật/tắt</strong> trường và đặt <strong>bắt buộc</strong>. Lưu các thay đổi đang chỉnh.</li><li><strong>Phản hồi (Responses):</strong> xem danh sách phản hồi đã thu thập, tải xuống.</li></ul><p>Ngoài ra có thể: đổi tiêu đề/mô tả, chuyển trạng thái (Nháp/Đang mở/Đã đóng), bật/tắt <strong>Nội Bộ</strong>, <strong>copy link công khai</strong> và <strong>xóa</strong> biểu mẫu.</p><div class="tip custom-block"><p class="custom-block-title">Chia sẻ biểu mẫu</p><p>Nhấn <strong>Copy link</strong> rồi gửi đường dẫn <code>/forms/{token}</code> cho người cần điền. Khi biểu mẫu ở trạng thái <strong>Đã đóng</strong>, link sẽ không nhận phản hồi mới.</p></div><h3 id="cong-khai-va-noi-bo" tabindex="-1">Công Khai và Nội Bộ <a class="header-anchor" href="#cong-khai-va-noi-bo" aria-label="Permalink to &quot;Công Khai và Nội Bộ&quot;">​</a></h3><p>Mỗi biểu mẫu có nhãn cho biết phạm vi truy cập, đổi bằng ô tích <strong>Nội Bộ</strong> ở trang quản lý:</p><ul><li>🌐 <strong>Công Khai</strong> (mặc định) — ai có link đều điền được, <strong>không cần đăng nhập</strong>. Dùng cho khảo sát, đăng ký, tuyển dụng…</li><li>🔒 <strong>Nội Bộ</strong> — chỉ tài khoản <strong>đã đăng nhập</strong> mới mở/điền được. Người chưa đăng nhập mở link sẽ được đưa về trang đăng nhập, đăng nhập xong tự quay lại đúng biểu mẫu.</li></ul><h3 id="nguoi-đien-bieu-mau-cong-khai" tabindex="-1">Người điền biểu mẫu (công khai) <a class="header-anchor" href="#nguoi-đien-bieu-mau-cong-khai" aria-label="Permalink to &quot;Người điền biểu mẫu (công khai)&quot;">​</a></h3><p>Người nhận link mở <code>/forms/{token}</code> mà <strong>không cần đăng nhập</strong>, điền các trường rồi gửi. Phản hồi được lưu về tab <strong>Phản hồi</strong> của biểu mẫu.</p><hr><h2 id="bieu-mau-thong-tin-nhan-viec-onboarding" tabindex="-1">Biểu mẫu thông tin nhận việc (Onboarding) <a class="header-anchor" href="#bieu-mau-thong-tin-nhan-viec-onboarding" aria-label="Permalink to &quot;Biểu mẫu thông tin nhận việc (Onboarding)&quot;">​</a></h2><p>Đây là biểu mẫu công khai cố định để <strong>nhân sự mới tự điền thông tin nhận việc</strong> trước khi được tạo tài khoản.</p><h3 id="cau-hinh-bieu-mau" tabindex="-1">Cấu hình biểu mẫu <a class="header-anchor" href="#cau-hinh-bieu-mau" aria-label="Permalink to &quot;Cấu hình biểu mẫu&quot;">​</a></h3><p>Cấu hình tại phân hệ <a href="/help/chuc-nang/nguon-nhan-luc.html">Onboarding</a> → tab <strong>Cấu hình biểu mẫu</strong>:</p><ul><li>Bật/tắt và đặt <strong>bắt buộc</strong> cho từng trường thông tin (chia theo nhóm: thông tin cá nhân, công việc…).</li><li>Cấu hình <strong>loại giấy tờ</strong> cần nộp (bắt buộc / cho phép nhiều tệp).</li></ul><h3 id="nhan-su-moi-đien-form" tabindex="-1">Nhân sự mới điền form <a class="header-anchor" href="#nhan-su-moi-đien-form" aria-label="Permalink to &quot;Nhân sự mới điền form&quot;">​</a></h3><ol><li>Gửi link cố định <code>/onboarding/thong-tin-nhan-su-dau-vao</code> cho nhân sự mới.</li><li>Nhân sự điền thông tin, đính kèm giấy tờ (mỗi tệp tối đa <strong>10MB</strong>) và gửi — tất cả trong một lần nộp, không cần đăng nhập.</li><li>Nếu biểu mẫu đang đóng, trang hiển thị thông báo tạm khóa.</li></ol><p><img src="'+u+'" alt="Biểu mẫu thông tin nhận việc (liên kết công khai)"></p><h3 id="luong-duyet-tao-tai-khoan" tabindex="-1">Luồng duyệt tạo tài khoản <a class="header-anchor" href="#luong-duyet-tao-tai-khoan" aria-label="Permalink to &quot;Luồng duyệt tạo tài khoản&quot;">​</a></h3><p>Sau khi nhân sự nộp, phòng nhân sự xử lý tại phân hệ Onboarding theo luồng:</p><blockquote><p>Chờ điền → <strong>Đã nộp</strong> → <strong>Đã xác nhận</strong> → <strong>Chờ QTV duyệt</strong> → <strong>Đã duyệt</strong> (tạo tài khoản) / <strong>Từ chối</strong></p></blockquote><p>Quản trị viên duyệt sẽ tạo tài khoản người dùng cho nhân sự mới từ chính dữ liệu đã khai.</p><div class="warning custom-block"><p class="custom-block-title">Phân biệt hai loại biểu mẫu</p><p><strong>Biểu mẫu thường</strong> (<code>/forms/{token}</code>) dùng để thu thập phản hồi bất kỳ. <strong>Biểu mẫu nhận việc</strong> (<code>/onboarding/...</code>) gắn với quy trình onboarding và tạo tài khoản nhân sự — đừng nhầm lẫn.</p></div><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Người nhận biểu mẫu có cần đăng nhập không?</strong> Không. Biểu mẫu mở qua liên kết (token) công khai nên người ngoài hệ thống vẫn điền được.</p><p><strong>Điền biểu mẫu nhận việc xong có tự thành nhân viên ngay không?</strong> Chưa. Dữ liệu phải qua bước <strong>Quản trị viên duyệt</strong> mới tạo tài khoản — tránh tạo nhầm.</p><p><strong>Sửa biểu mẫu sau khi đã gửi đi được không?</strong> Nên tạo bản mới hoặc thu hồi liên kết cũ; dữ liệu đã nộp vẫn được giữ để tra cứu.</p><h2 id="buoc-tiep-theo" tabindex="-1">Bước tiếp theo <a class="header-anchor" href="#buoc-tiep-theo" aria-label="Permalink to &quot;Bước tiếp theo&quot;">​</a></h2><ul><li>Duyệt hồ sơ nhận việc và tạo tài khoản → <a href="/help/quan-tri/nguoi-dung.html">Người dùng</a>.</li><li>Liên kết với tuyển dụng → <a href="/help/chuc-nang/nguon-nhan-luc.html">Nguồn Nhân Lực</a>.</li></ul><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/nguon-nhan-luc.html">Nguồn Nhân Lực</a> · <a href="/help/quan-tri/nguoi-dung.html">Người dùng</a> · <a href="/help/chuc-nang/nhan-su.html">Quản Lý Hồ Sơ</a></p>',40)])])}const d=i(g,[["render",r]]);export{p as __pageData,d as default};
